INSERT INTO data_plane_type (type_name,param_spec,capability_spec,"desc",desc_en,type_display_name) VALUES
	('elastic','{"name":"root","type":"object","children":[{"name":"address","type":"string","desc":"Elastic 地址, 例如: https://cluster.es.region.cloud.es.io","desc_en":"Elastic address, e.g. https://cluster.es.region.cloud.es.io"},{"name":"authType","type":"string","desc":"认证方式: apiKey 或 basic","desc_en":"Auth type: apiKey or basic","optional":true},{"name":"apiKey","type":"string","desc":"Elastic API Key","desc_en":"Elastic API Key","optional":true},{"name":"username","type":"string","desc":"Elastic 用户名","desc_en":"Elastic username","optional":true},{"name":"password","type":"string","desc":"Elastic 密码","desc_en":"Elastic password","optional":true},{"name":"logIndexPattern","type":"string","desc":"日志索引或 data stream pattern, 例如: logs-*","desc_en":"Log index or data stream pattern, e.g. logs-*","optional":true},{"name":"traceIndexPattern","type":"string","desc":"Trace/APM 索引 pattern, 例如: traces-*","desc_en":"Trace/APM index pattern, e.g. traces-*","optional":true},{"name":"metricsIndexPattern","type":"string","desc":"Metrics 索引 pattern, 例如: metrics-*","desc_en":"Metrics index pattern, e.g. metrics-*","optional":true},{"name":"environment","type":"string","desc":"服务环境过滤值","desc_en":"Service environment filter","optional":true},{"name":"serviceNameField","type":"string","desc":"服务名字段覆盖","desc_en":"Service name field override","optional":true},{"name":"hostNameField","type":"string","desc":"主机名字段覆盖","desc_en":"Host name field override","optional":true},{"name":"containerIdField","type":"string","desc":"容器 ID 字段覆盖","desc_en":"Container ID field override","optional":true},{"name":"namespaceField","type":"string","desc":"Kubernetes Namespace 字段覆盖","desc_en":"Kubernetes namespace field override","optional":true},{"name":"podNameField","type":"string","desc":"Pod 名字段覆盖","desc_en":"Pod name field override","optional":true},{"name":"logLevelField","type":"string","desc":"日志级别字段覆盖","desc_en":"Log level field override","optional":true},{"name":"messageField","type":"string","desc":"日志消息字段覆盖","desc_en":"Log message field override","optional":true}]}','["RedMetric","ServiceInstance","Topology","Log","Trace","Metrics"]','','','Elastic')
